package redact

import (
	_ "embed" // vendor_rules.json
	"encoding/json"
	"regexp"
	"runtime"
	"strings"
	"sync"
)

// vendorRulesJSON is generated by tools/genrules from the betterleaks default
// configuration (MIT; LICENSE-betterleaks). Regenerate, do not edit:
//
//	go run ./tools/genrules -config <betterleaks.toml> \
//	    -source betterleaks/betterleaks@<sha>:config/betterleaks.toml \
//	    -out internal/redact/vendor_rules.json
//
//go:embed vendor_rules.json
var vendorRulesJSON []byte

type vendorFilter struct {
	EntropyBelow     float64  `json:"entropyBelow"`
	EntropyInclusive bool     `json:"entropyInclusive"`
	SecretMatches    []string `json:"secretMatches"`
	SecretContains   []string `json:"secretContains"`
	SecretMustMatch  []string `json:"secretMustMatch"`

	matches, mustMatch []*regexp.Regexp
}

type vendorRule struct {
	ID         string        `json:"id"`
	Regex      string        `json:"regex"`
	Keywords   []string      `json:"keywords"`
	ValueGroup int           `json:"valueGroup"`
	Filter     *vendorFilter `json:"filter"`

	once sync.Once
	re   *regexp.Regexp
}

type vendorTable struct {
	Source       string        `json:"source"`
	GlobalFilter vendorFilter  `json:"globalFilter"`
	Rules        []*vendorRule `json:"rules"`

	keywords *matcher
	byKW     [][]int // keyword index → rule indexes
}

var (
	tableOnce sync.Once
	table     vendorTable
)

// vendorRules parses the embedded table once. Rule regexes compile lazily,
// on the first text that carries one of the rule's keywords.
func vendorRules() *vendorTable {
	tableOnce.Do(func() {
		if err := json.Unmarshal(vendorRulesJSON, &table); err != nil {
			panic("redact: vendor_rules.json: " + err.Error())
		}
		table.GlobalFilter.compile()
		index := map[string]int{}
		var kws []string
		for i, r := range table.Rules {
			if r.Filter != nil {
				r.Filter.compile()
			}
			for _, k := range r.Keywords {
				j, ok := index[k]
				if !ok {
					j = len(kws)
					index[k] = j
					kws = append(kws, k)
					table.byKW = append(table.byKW, nil)
				}
				table.byKW[j] = append(table.byKW[j], i)
			}
		}
		table.keywords = newMatcher(kws)
	})
	return &table
}

func (f *vendorFilter) compile() {
	for _, p := range f.SecretMatches {
		f.matches = append(f.matches, regexp.MustCompile(p))
	}
	for _, p := range f.SecretMustMatch {
		f.mustMatch = append(f.mustMatch, regexp.MustCompile(p))
	}
}

// discards reports whether the filter rejects a candidate secret.
func (f *vendorFilter) discards(secret string) bool {
	if f == nil {
		return false
	}
	if f.EntropyBelow > 0 {
		h := shannon(secret)
		if h < f.EntropyBelow || (f.EntropyInclusive && h == f.EntropyBelow) {
			return true
		}
	}
	for _, re := range f.matches {
		if re.MatchString(secret) {
			return true
		}
	}
	for _, s := range f.SecretContains {
		if strings.Contains(secret, s) {
			return true
		}
	}
	if len(f.mustMatch) > 0 {
		for _, re := range f.mustMatch {
			if re.MatchString(secret) {
				return false
			}
		}
		return true
	}
	return false
}

func (r *vendorRule) regex() *regexp.Regexp {
	r.once.Do(func() { r.re = regexp.MustCompile(r.Regex) })
	return r.re
}

// secretSpan picks the value a match reports: the rule's valueGroup, else the
// first non-empty capture group, else the whole match (betterleaks semantics).
func (r *vendorRule) secretSpan(m []int) (int, int) {
	if r.ValueGroup > 0 {
		if 2*r.ValueGroup+1 < len(m) {
			return m[2*r.ValueGroup], m[2*r.ValueGroup+1]
		}
		return -1, -1
	}
	for g := 1; 2*g+1 < len(m); g++ {
		if m[2*g] >= 0 && m[2*g+1] > m[2*g] {
			return m[2*g], m[2*g+1]
		}
	}
	return m[0], m[1]
}

// vendorSpans runs every rule whose keyword occurs in text. lower is
// asciiLower(text).
func vendorSpans(text, lower string) []span {
	t := vendorRules()
	seenKW := make([]bool, len(t.byKW))
	t.keywords.present(lower, seenKW)
	active := make([]bool, len(t.Rules))
	for k, seen := range seenKW {
		if seen {
			for _, i := range t.byKW[k] {
				active[i] = true
			}
		}
	}
	var rules []*vendorRule
	for i, r := range t.Rules {
		if active[i] {
			rules = append(rules, r)
		}
	}
	// Rules are independent, so a large text runs them in parallel; the
	// result is the same as running them in order.
	found := make([][]span, len(rules))
	if len(text) >= parallelMin && len(rules) > 1 {
		var wg sync.WaitGroup
		sem := make(chan struct{}, runtime.GOMAXPROCS(0))
		for i, r := range rules {
			wg.Add(1)
			sem <- struct{}{}
			go func() {
				defer func() { <-sem; wg.Done() }()
				found[i] = t.ruleSpans(r, text)
			}()
		}
		wg.Wait()
	} else {
		for i, r := range rules {
			found[i] = t.ruleSpans(r, text)
		}
	}
	var out []span
	for _, f := range found {
		out = append(out, f...)
	}
	return out
}

// parallelMin is the text size from which rules run concurrently.
const parallelMin = 32 << 10

func (t *vendorTable) ruleSpans(r *vendorRule, text string) []span {
	var out []span
	for _, m := range r.regex().FindAllStringSubmatchIndex(text, -1) {
		s, e := r.secretSpan(m)
		if s < 0 || e <= s {
			continue
		}
		secret := text[s:e]
		if r.Filter.discards(secret) || t.GlobalFilter.discards(secret) || heldOut(secret) {
			continue
		}
		out = append(out, span{s, e, VendorRule})
	}
	return out
}
